const grpc = require('@grpc/grpc-js');
const protoLoader = require('@grpc/proto-loader');
const crypto = require('crypto');

// Feature flags loaded from config service
const featureFlags = {
  enableUnicodeNormalization: true,
  enableStrictEncoding: true,
  enablePathValidation: true,
  enableLegacyCompat: true,
  maxPathDepth: 10
};

// Simulated file store
const fileStore = {
  '/public/readme.txt': 'Welcome to the service',
  '/public/docs/api.txt': 'API documentation',
  '/private/secrets.txt': 'SECRET_KEY=supersecret123',
  '/private/admin/config.txt': 'admin_password=hunter2'
};

function normalizeEncoding(input) {
  if (!featureFlags.enableUnicodeNormalization) return input;
  // NFC normalization for consistent Unicode handling
  return input.normalize('NFC');
}

function decodePathSegment(segment) {
  if (!featureFlags.enableStrictEncoding) return segment;
  // Decode percent-encoded characters
  try {
    return decodeURIComponent(segment);
  } catch (e) {
    return segment;
  }
}

function validatePathTraversal(path) {
  if (!featureFlags.enablePathValidation) return true;
  // Check for path traversal attempts
  const segments = path.split('/');
  let depth = 0;
  for (const seg of segments) {
    if (seg === '..') depth--;
    else if (seg !== '' && seg !== '.') depth++;
    if (depth < 0) return false;
  }
  return true;
}

function sanitizePath(rawPath) {
  // Step 1: Unicode normalization
  let path = normalizeEncoding(rawPath);

  // Step 2: Validate before decoding (check raw form)
  if (!validatePathTraversal(path)) {
    return null;
  }

  // Step 3: Decode path segments
  const segments = path.split('/');
  const decodedSegments = segments.map(seg => decodePathSegment(seg));
  let decodedPath = decodedSegments.join('/');

  // Step 4: Legacy compatibility - handle double encoding
  if (featureFlags.enableLegacyCompat) {
    // Legacy clients may double-encode; decode again for compat
    try {
      const reDecoded = decodeURIComponent(decodedPath);
      if (reDecoded !== decodedPath) {
        decodedPath = reDecoded;
      }
    } catch (e) {
      // Not double-encoded, use as-is
    }
  }

  // Step 5: Final cleanup - remove redundant slashes
  decodedPath = decodedPath.replace(/\/+/g, '/');

  return decodedPath;
}

function resolveFilePath(basePath, userPath) {
  const sanitized = sanitizePath(userPath);
  if (sanitized === null) {
    return null;
  }

  // Ensure path starts with base
  const fullPath = basePath + sanitized;
  return fullPath;
}

function getFile(call, callback) {
  const requestPath = call.request.path;
  const clientVersion = call.request.clientVersion || 'modern';

  // Audit log
  console.log(`[AUDIT] File request: path=${requestPath}, client=${clientVersion}`);

  const resolvedPath = resolveFilePath('/public', requestPath);

  if (resolvedPath === null) {
    callback({
      code: grpc.status.PERMISSION_DENIED,
      message: 'Path traversal detected'
    });
    return;
  }

  // Check if file exists in store
  if (fileStore[resolvedPath]) {
    callback(null, {
      content: fileStore[resolvedPath],
      path: resolvedPath
    });
  } else {
    callback({
      code: grpc.status.NOT_FOUND,
      message: 'File not found'
    });
  }
}

function updateFeatureFlag(call, callback) {
  const { flagName, flagValue } = call.request;

  // Only allow known flags
  if (!(flagName in featureFlags)) {
    callback({
      code: grpc.status.INVALID_ARGUMENT,
      message: 'Unknown feature flag'
    });
    return;
  }

  featureFlags[flagName] = flagValue;
  console.log(`[CONFIG] Feature flag updated: ${flagName}=${flagValue}`);

  callback(null, { success: true, message: `Flag ${flagName} updated` });
}

function startServer() {
  const server = new grpc.Server();

  // Service definition inline for simplicity
  const serviceDefinition = {
    getFile: { path: '/FileService/GetFile', requestStream: false, responseStream: false },
    updateFeatureFlag: { path: '/FileService/UpdateFeatureFlag', requestStream: false, responseStream: false }
  };

  server.addService(serviceDefinition, { getFile, updateFeatureFlag });

  server.bindAsync('0.0.0.0:50051', grpc.ServerCredentials.createInsecure(), (err, port) => {
    if (err) throw err;
    console.log(`gRPC server running on port ${port}`);
    server.start();
  });
}

startServer();

module.exports = { sanitizePath, resolveFilePath, validatePathTraversal, featureFlags };
